import{_ as o,a as t,b as a,c as n,d as r,e as i}from"./chunks/19-saaw-governed-self-morphing-v2.CtEM6EK-.js";import{_ as s,o as l,c,a2 as d}from"./chunks/framework.Cm6XCzck.js";const w=JSON.parse('{"title":"Trace Is Not Governance: From Work Facts to SaaW","description":"","frontmatter":{"title":"Trace Is Not Governance: From Work Facts to SaaW","date":"2026-08-14","column":"industry-architecture","category":"visual-essay","version":"V1.0","summary":"Starting from the difference between execution traces and governance, this visual essay explains how TMPA, FCoP, CodeFlowMu, the Meta-Development Runtime, Digital Employee Packages, and governed Self-Morphing form an engineering path toward SaaW.","item_id":"VISUAL-ESSAY-20260814-TRACE-GOVERNANCE-SAAW-EN","lifecycle":"Published","cover":"/assets/covers/01-saaw-manifesto-cover-agent-worker.png","visualization":"/assets/covers/16-saaw-tmpa-four-rules-v2.svg","visualization_2":"/assets/covers/17-saaw-fcop-lifecycle-v2.svg","visualization_3":"/assets/covers/18-saaw-codeflowmu-runtime-boundary-v2.svg","visualization_4":"/assets/covers/19-saaw-governed-self-morphing-v2.svg","evidence_status":"Derived from the published SaaW V1.1 manifesto and TMPA V1.0 publication line","citation_status":"TMPA V1.0 DOI and public engineering repositories linked","editing_status":"Published","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/industry/2026-08-14-trace-governance-saaw-visual-essay.md","filePath":"en/industry/2026-08-14-trace-governance-saaw-visual-essay.md","lastUpdated":1786641132000}'),p={name:"en/industry/2026-08-14-trace-governance-saaw-visual-essay.md"};function u(g,e,h,m,v,f){return l(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="trace-is-not-governance-from-work-facts-to-saaw" tabindex="-1">Trace Is Not Governance: From Work Facts to SaaW <a class="header-anchor" href="#trace-is-not-governance-from-work-facts-to-saaw" aria-label="Permalink to &quot;Trace Is Not Governance: From Work Facts to SaaW&quot;">​</a></h1><h2 id="an-engineering-lineage-through-tmpa-fcop-codeflowmu-and-self-morphing" tabindex="-1">An engineering lineage through TMPA, FCoP, CodeFlowMu, and Self-Morphing <a class="header-anchor" href="#an-engineering-lineage-through-tmpa-fcop-codeflowmu-and-self-morphing" aria-label="Permalink to &quot;An engineering lineage through TMPA, FCoP, CodeFlowMu, and Self-Morphing&quot;">​</a></h2><p><a href="/joinwell52/en/industry/2026-08-10-saaw-software-as-an-agent-worker">Read the complete 23-section manifesto, <em>From SaaS to SaaW</em></a></p><p><a href="/joinwell52/zh/industry/2026-08-14-trace-governance-saaw-visual-essay">中文版</a></p><p><a href="/joinwell52/assets/covers/01-saaw-manifesto-cover-agent-worker.png"><img src="'+o+'" alt="SaaW — Software as an Agent Worker"></a></p><p>An Agent called tools, modified files, and finally returned <code>completed</code>.</p><p>What does that prove?</p><p>It proves only that <strong>an execution occurred</strong>.</p><p>It does not automatically prove that the task was legally completed, the tests were confirmed, the delivery was reviewed, conflicts were resolved, or any role had the authority to move the task into its next state.</p><p>This is the architectural boundary that long-running Agent systems most often overlook:</p><blockquote><p><strong>Trace is not Governance.</strong></p></blockquote><p><a href="/joinwell52/assets/covers/15-saaw-trace-vs-governance-v2.svg"><img src="'+t+'" alt="Trace is not Governance: the difference between execution events and governed work state"></a></p><p><em>Figure 1. A trace records events. Governance reconstructs legal work state from durable facts, rules, responsibility, and authority.</em></p><h2 id="_1-why-an-execution-trace-is-not-enough" tabindex="-1">1. Why an execution trace is not enough <a class="header-anchor" href="#_1-why-an-execution-trace-is-not-enough" aria-label="Permalink to &quot;1. Why an execution trace is not enough&quot;">​</a></h2><p>A trace can answer which tool a model called, when an operation occurred, and what the tool returned.</p><p>Real work requires another set of answers:</p><ul><li>Who authorized the task?</li><li>Who formally accepted responsibility?</li><li>Which artifact represents the official delivery?</li><li>Can the test result be independently verified?</li><li>Who performed the review?</li><li>Is the current lifecycle state legal?</li><li>Do unresolved conflicts, missing evidence, or dangling references remain?</li><li>Who continues after a process restart?</li></ul><p>Adding more log lines does not solve these questions. Logs remain system events. Governance concerns work facts, responsibility, and the legal effect of decisions.</p><p>The first step toward a digital employee is therefore not giving an Agent more tools. It is making work facts independent of the Agent session.</p><h2 id="_2-tmpa-making-work-facts-reconstructable" tabindex="-1">2. TMPA: Making work facts reconstructable <a class="header-anchor" href="#_2-tmpa-making-work-facts-reconstructable" aria-label="Permalink to &quot;2. TMPA: Making work facts reconstructable&quot;">​</a></h2><p><strong>TMPA (Textual Multi-Agent Process Architecture)</strong> is a text-message-based asynchronous multi-agent process architecture designed for SME-first, minimum-infrastructure environments.</p><p>It is not an Agent scheduler or a central runtime. TMPA addresses how tasks, responsibility, evidence, conflicts, and audit state become valid when Agents and humans collaborate asynchronously over time.</p><p>Its core consists of four connected rules:</p><blockquote><p><strong>Text carries durable messages and state; each writer maintains its own local serial stream; multiple serial streams advance asynchronously to form parallel collaboration; readers aggregate available evidence to reconstruct process, responsibility, lifecycle, conflicts, and audit state.</strong></p></blockquote><p><a href="/joinwell52/assets/covers/16-saaw-tmpa-four-rules-v2.svg"><img src="'+a+'" alt="The four TMPA rules and reader-side fact reconstruction"></a></p><p><em>Figure 2. Each actor appends its own facts. Cross-stream references form a partial order. The Reader aggregates evidence without overwriting conflict.</em></p><p>The important point is not simply “using text instead of a database.” Two deeper principles matter.</p><p>First, responsibility needs a clear source. PM, DEV, QA, and human decision-makers preserve their own local fact streams instead of rewriting another actor&#39;s history.</p><p>Second, state is not merely the last value of a field. A Reader recalculates current state from objects such as <code>Task</code>, <code>Acceptance</code>, <code>Report</code>, <code>Review</code>, <code>Decision</code>, <code>Issue</code>, and <code>Correction</code>.</p><p>Models may change and processes may restart, but established work facts do not disappear with the session.</p><h2 id="_3-fcop-bringing-governance-semantics-into-project-collaboration" tabindex="-1">3. FCoP: Bringing governance semantics into project collaboration <a class="header-anchor" href="#_3-fcop-bringing-governance-semantics-into-project-collaboration" aria-label="Permalink to &quot;3. FCoP: Bringing governance semantics into project collaboration&quot;">​</a></h2><p>Theory and specifications need an executable form of coordination.</p><p><strong>FCoP (File-based Coordination Protocol) is a multi-agent behavioral-governance protocol that uses the filesystem as its sole synchronization primitive.</strong></p><p>Its project-visible Profile can be summarized as follows:</p><ul><li><strong>Directory is state:</strong> <code>inbox → active → review → done → archive</code>.</li><li><strong>Filename is routing:</strong> sender, recipient, object type, and sequence express identity.</li><li><strong>Content is payload:</strong> Markdown and frontmatter carry tasks, reports, references, and evidence.</li><li><strong>Atomic movement is synchronization:</strong> lifecycle transitions use <code>os.rename()</code>.</li></ul><p><a href="/joinwell52/assets/covers/17-saaw-fcop-lifecycle-v2.svg"><img src="'+n+'" alt="The FCoP project-visible lifecycle and shared fact plane"></a></p><p><em>Figure 3. Lifecycle change moves a project-visible work object instead of overwriting a central status field. Humans, Agents, Readers, and operations tools inspect the same fact plane.</em></p><p>FCoP is not merely a way to “send messages with files.” It makes handoffs, reports, reviews, decisions, issues, and recovery paths observable, referenceable, and auditable.</p><p>Its boundary is equally important: FCoP governs collaborative behavior. It does not provide model reasoning, process scheduling, identity authentication, or resource allocation, and it is not a complete Agent Runtime.</p><h2 id="_4-codeflowmu-bringing-roles-tools-and-governance-into-real-execution" tabindex="-1">4. CodeFlowMu: Bringing roles, tools, and governance into real execution <a class="header-anchor" href="#_4-codeflowmu-bringing-roles-tools-and-governance-into-real-execution" aria-label="Permalink to &quot;4. CodeFlowMu: Bringing roles, tools, and governance into real execution&quot;">​</a></h2><p>If TMPA defines work facts and governance semantics, and FCoP provides a project-visible file-driven coordination protocol, then <strong>CodeFlowMu addresses how those semantics and protocols enter a real Agent runtime world.</strong></p><p>Its engineering starting point is not a giant central Agent.</p><p>Reasoning remains in mature model ecosystems. Browsers, APIs, CLIs, MCP, and business systems perform actual operations. CodeFlowMu concentrates on role orchestration, responsibility boundaries, Skill routing, lifecycle, FCoP integration, reports, reviews, recovery, and human decisions.</p><p><a href="/joinwell52/assets/covers/18-saaw-codeflowmu-runtime-boundary-v2.svg"><img src="'+r+'" alt="The CodeFlowMu engineering runtime boundary"></a></p><p><em>Figure 4. Models reason and tools act. CodeFlowMu organizes work, FCoP carries facts, and TMPA guides governance semantics.</em></p><p>The three are therefore not three similar products:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Responsibility</th><th>Non-responsibility</th></tr></thead><tbody><tr><td>TMPA</td><td>Defines which work facts can become valid and reconstructable</td><td>Does not schedule or execute work</td></tr><tr><td>FCoP</td><td>Brings those facts into project-visible collaboration</td><td>Is not a complete Agent Runtime</td></tr><tr><td>CodeFlowMu</td><td>Runs roles, tools, protocols, lifecycle, recovery, and governance</td><td>Does not use runtime events as a substitute for business decisions</td></tr></tbody></table><p>Only with these boundaries can a system avoid treating “the Agent returned completed” as “the organization accepted the delivery.”</p><h2 id="_5-the-meta-development-runtime-development-capability-becomes-production-capability" tabindex="-1">5. The Meta-Development Runtime: Development capability becomes production capability <a class="header-anchor" href="#_5-the-meta-development-runtime-development-capability-becomes-production-capability" aria-label="Permalink to &quot;5. The Meta-Development Runtime: Development capability becomes production capability&quot;">​</a></h2><p>The most important thing about CodeFlowMu is not only that multiple Agents can develop software together.</p><blockquote><p><strong>More importantly, that development capability can itself become production capability for the next generation of digital employees.</strong></p></blockquote><p>We call this form the <strong>Meta-Development Runtime</strong>.</p><p>Roles such as PM, DEV, QA, and OPS can build more than conventional software. They can combine job responsibilities, workflows, Skills, permissions, governance policies, validation rules, runtime configuration, recovery rules, and human decision gates into a:</p><blockquote><p><strong>Digital Employee Package: turning a digital employee into an engineered product.</strong></p></blockquote><p>A position capability can then be defined, developed, tested, versioned, deployed, upgraded, and rolled back like software.</p><h2 id="_6-self-morphing-developing-itself-under-governance" tabindex="-1">6. Self-Morphing: “Developing itself” under governance <a class="header-anchor" href="#_6-self-morphing-developing-itself-under-governance" aria-label="Permalink to &quot;6. Self-Morphing: “Developing itself” under governance&quot;">​</a></h2><p><strong>Self-Morphing</strong> does not mean allowing a running Agent to rewrite itself arbitrarily, nor does it mean an unlimited recursion of Agents creating Agents.</p><p>It describes a strictly isolated and recoverable improvement loop. Production work emits evidence. Evidence exposes a capability gap. The Meta-Development Runtime designs an improvement and produces a new Digital Employee Package. Only after isolated validation and explicit authorization may that version enter the next work cycle.</p><p><a href="/joinwell52/assets/covers/19-saaw-governed-self-morphing-v2.svg"><img src="'+i+'" alt="The governed Meta-Development and Self-Morphing loop"></a></p><p><em>Figure 5. Evidence can enter meta-development, but meta-development cannot rewrite the live production runtime. Validation and authority control deployment, and a rollback path always remains available.</em></p><p>The complete loop is:</p><blockquote><p><strong>Work → Evidence → Gap → Improvement → Isolated Validation → Human or Governance Authorization → Deployment → New Work Cycle</strong></p></blockquote><p>If the source of a change is not traceable, tests are not reproducible, deployment is not authorized, the running version is not identifiable, or failure cannot be rolled back, then “self-evolution” is only unauditable automatic rewriting.</p><h2 id="_7-humans-do-not-disappear-they-leave-the-operation-layer" tabindex="-1">7. Humans do not disappear; they leave the operation layer <a class="header-anchor" href="#_7-humans-do-not-disappear-they-leave-the-operation-layer" aria-label="Permalink to &quot;7. Humans do not disappear; they leave the operation layer&quot;">​</a></h2><p>SaaW does not remove humans from the system.</p><p>Low-risk, reversible, in-policy work such as retrieval, organization, validation, reporting, and synchronization can increasingly be performed by digital employees. External publication, irreversible modification, money, credentials, privacy, and policy exceptions must stop at a human authority boundary.</p><p>Humans no longer need to perform every click and data transfer. Their responsibilities move toward:</p><ul><li>defining objectives and authority boundaries;</li><li>handling conflict and exceptions;</li><li>reviewing consequential evidence;</li><li>approving, rejecting, or requesting rework;</li><li>taking final responsibility for high-impact outcomes.</li></ul><p>In SaaS, humans usually remain in the software operation layer. In SaaW, humans increasingly move into governance and final authority.</p><h2 id="_8-saaw-when-software-begins-to-carry-work" tabindex="-1">8. SaaW: When software begins to carry work <a class="header-anchor" href="#_8-saaw-when-software-begins-to-carry-work" aria-label="Permalink to &quot;8. SaaW: When software begins to carry work&quot;">​</a></h2><p><strong>SaaW (Software as an Agent Worker)</strong> is the higher-level name for this transition. Software stops being only a collection of capabilities operated by people and begins to carry work continuously under explicit job responsibilities, authority boundaries, and governance rules.</p><p>It is not a new chat window, and it is not created by simply adding an Agent. A real digital work subject needs a role, an environment, Skills, permissions, state, governance, evidence, recovery, and human authority boundaries.</p><p>Validated capability must remain separate from the research frontier.</p><p>The public engineering foundation available today includes the TMPA V1.0 architecture paper, core specification, and implementation case; the FCoP protocol and implementation; and the open CodeFlowMu engineering runtime environment. The implementation case pins CodeFlowMu v1.8.0 and records a <strong>14/14</strong> validation result against TMPA S1.0.</p><p>Standardized Digital Employee Packages, a standardized Agent PC, domain Work Runtimes, and broader Self-Morphing validation remain research and future engineering work.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The decisive change from Agent systems to digital employees is not that a model becomes more human-like. It is that work gains facts, responsibility, evidence, recovery, and authority structures that exist independently of the model session.</p><blockquote><p><strong>TMPA makes work facts valid. FCoP makes coordination facts visible. CodeFlowMu brings them into real execution. The Meta-Development Runtime then turns runtime evidence into Digital Employee Packages and improves them through governed Self-Morphing, ultimately pointing toward SaaW.</strong></p></blockquote><p>Software was once a tool.<br> Then it became a service.<br> Now, it is beginning to work.</p><blockquote><p><strong>From Software Market to Digital Labor Market.</strong></p></blockquote><hr><ul><li><strong>Complete manifesto:</strong> <a href="/joinwell52/en/industry/2026-08-10-saaw-software-as-an-agent-worker">From SaaS to SaaW: When a Codebase Starts “Developing Itself”</a></li><li><strong>TMPA V1.0 DOI:</strong> <a href="https://doi.org/10.5281/zenodo.21888488" target="_blank" rel="noreferrer">10.5281/zenodo.21888488</a></li><li><strong>FCoP:</strong> <a href="https://github.com/joinwell52-AI/FCoP" target="_blank" rel="noreferrer">GitHub Repository</a></li><li><strong>CodeFlowMu:</strong> <a href="https://github.com/joinwell52-AI/CodeFlowMu-open" target="_blank" rel="noreferrer">Open Engineering Runtime</a></li><li><strong>Version status:</strong> V1.0 · Published</li></ul>',82)])])}const k=s(p,[["render",u]]);export{w as __pageData,k as default};
